import{_ as t,o as e,c as a,Q as i}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Robobrick","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/machines/robobrick/index.md","filePath":"guide/machine_files/machines/robobrick/index.md","lastUpdated":1790618281000}'),o={name:"guide/machine_files/machines/robobrick/index.md"},r=i('<h1 id="robobrick" tabindex="-1">Robobrick <a class="header-anchor" href="#robobrick" aria-label="Permalink to &quot;Robobrick&quot;">​</a></h1><p>The Robobrick (H&amp;M Robi-One Brick Slip Robot) glues brick slips onto the outside face of a panel. It is a station of an H&amp;M line, and its layers are written into the panel&#39;s <a href="/guide/machine_files/formats/panel_mob2/">MOB v2 file</a> together with those of the other stations.</p><nav class="table-of-contents"><ul><li><a href="#setting-it-up">Setting it up</a></li><li><a href="#which-parts-become-bricks">Which parts become bricks</a></li><li><a href="#what-it-writes">What it writes</a></li><li><a href="#job-options">Job options</a></li><li><a href="#drawings">Drawings</a></li></ul></nav><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>In <strong>Production Settings &gt; Machine Settings</strong>, create a setup with the model <em>H&amp;M Robi-One Brick Slip Robot</em>.</li><li>Upload the machine&#39;s configuration file (XML) in the <strong>Machine file</strong> tab.</li><li>In <strong>Production lines</strong>, link the setup to a station with <strong>Machine station</strong>, and give that station the zones that carry the bricks.</li></ol><p>The <strong>Machine setup</strong> tab holds only the two <strong>Blocker Height</strong> values, used to <a href="/guide/machine_files/formats/panel_mob2/#general">shift</a> the panel against the table stops.</p><h2 id="which-parts-become-bricks" tabindex="-1">Which parts become bricks <a class="header-anchor" href="#which-parts-become-bricks" aria-label="Permalink to &quot;Which parts become bricks&quot;">​</a></h2><p>Only the parts your parsing setup marks as machine bricks: the <strong>Bricks / Stones</strong> category, plus the <strong>Bricks: Machine Flag</strong> rule of the Operations and machines tab. Bricks laid by hand stay out of the file. Glue lines and glue areas of the model are written next to them.</p><p>See: <a href="/guide/management/ifcps/#bricks-machine-flag">IFC Parsing Setup</a></p><h2 id="what-it-writes" tabindex="-1">What it writes <a class="header-anchor" href="#what-it-writes" aria-label="Permalink to &quot;What it writes&quot;">​</a></h2><p>For each of its zones, a layer named <em>Glue and bricks</em> with:</p><ul><li><code>MSN</code> — one row per brick: its size, position, angle, name and id.</li><li><code>MSNGLUE</code> — the glue of each brick.</li></ul><h2 id="job-options" tabindex="-1">Job options <a class="header-anchor" href="#job-options" aria-label="Permalink to &quot;Job options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Choices</th><th>Default</th></tr></thead><tbody><tr><td><strong>Max distance between Glue lines for joining them</strong></td><td>mm</td><td>100</td></tr><tr><td><strong>UUID Export mode</strong></td><td>IFC GID (base64) (produuz.it standard), IFC GID converted to canonical UUID v4</td><td>IFC GID (base64)</td></tr></tbody></table><p>Glue lines closer than the distance are joined into one. <strong>UUID Export mode</strong> decides how the id of each brick is written: as the IFC stores it, or converted to the usual UUID form your other software may expect. <strong>Use optimized mode</strong> is also shown and has no effect at the moment.</p><h2 id="drawings" tabindex="-1">Drawings <a class="header-anchor" href="#drawings" aria-label="Permalink to &quot;Drawings&quot;">​</a></h2><p>With the report come a <strong>Bricks</strong> and an <strong>RB Glue</strong> drawing per zone, when the <strong>SVG Drawings</strong> switches of the station that owns zone 0 allow them.</p>',17),n=[r];function s(h,c,l,d,p,b){return e(),a("div",null,n)}const u=t(o,[["render",s]]);export{m as __pageData,u as default};
